oxy_webhelp_navlinks = {"rcv_prep_location_creation-d39307e10780":{"topics":[{"title":"Evaluation of options for RCV location creation","shortdesc":"<p class=\"shortdesc\">When creating a Rubrik Cloud Vault location, it is important to evaluate the         available options for adding the location. By evaluating these options, you can ensure that         your data protection strategy is cost-effective, resilient, and aligned with your recovery         objectives.<\/p>","href":"saas\/rcv_evaluate_options_loc_creation.html","attributes":{"data-id":"rcv_evaluate_options_loc_creation"},"menu":{"hasChildren":false},"tocID":"rcv_evaluate_options_loc_creation-d39307e10791","next":"rcv_evaluate_options_loc_creation-d39307e10791"},{"title":"Generating an RSA key","shortdesc":"<p class=\"shortdesc\">Generate an RSA key pair before creating an archival location that uses RSA key         (Bring Your Own Key) encryption.<\/p>","href":"common\/generating_an_rsa_key_2.html","attributes":{"data-id":"generating_an_rsa_key"},"menu":{"hasChildren":false},"tocID":"generating_an_rsa_key-d39307e10910","topics":[]},{"title":"Rubrik Cloud Vault best practices","shortdesc":"<p class=\"shortdesc\">Information about the Rubrik Cloud Vault best practices, which aim to optimize data         protection and compliance.<\/p>","href":"saas\/rcv_best_practices.html","attributes":{"data-id":"rcv_best_practices"},"menu":{"hasChildren":false},"tocID":"rcv_best_practices-d39307e10921","topics":[]}]}};